Figure.Script:
            procedure AddTexture(TextureName, x, y, z, nx, ny, nz, Rotate);
            begin
              PartNo := CallGlobal('GetVisiblePartContaining', x, y, z);
              FaceNo := CallGlobal('FindFaceByNorm', PartNo, nx, ny, nz);
              CallGlobal('SetTexture', TextureName, PartNo, FaceNo, Rotate);
            end;

            AddTexture('Wolf',    -W,-W,-W, -1, 0, 0,  1);
            AddTexture('Wolf',    -W,-W,-W,  0,-1, 0,  1);
            AddTexture('Wolf',    -W,-W,-W,  0, 0,-1,  1);
                                  
            AddTexture('Wolf',     W, W,-W,  1, 0, 0,  1);
            AddTexture('Wolf',     W, W,-W,  0, 1, 0,  1);
            AddTexture('Wolf',     W, W,-W,  0, 0,-1,  1);
                                  
            AddTexture('Goat',     W,-W, 0,  1, 0, 0,  0);
            AddTexture('Goat',     W,-W, 0,  0,-1, 0,  2);
                                 
            AddTexture('Goat',    -W, W, 0, -1, 0, 0,  0);
            AddTexture('Goat',    -W, W, 0,  0, 1, 0,  2);

            AddTexture('Cabbage',  0, 0, W,  0, 0, 1,  3);

            // Add tenon or groove to every gray side
            for PartNo := 0 to 26 do begin
              Goat := False;
              Wolf := False;
              Cabbage := False;
              for FaceNo := 0 to 5 do begin
                TextureName := CallGlobal('GetTexture', PartNo, FaceNo);
                if TextureName = 'Wolf' then
                  Wolf := True;
                if TextureName = 'Goat' then
                  Goat := True;
                if TextureName = 'Cabbage' then
                  Cabbage := True;
              end;
              for FaceNo := 0 to 5 do
                if CallGlobal('GetColor', PartNo, FaceNo) = '-1' then begin // if gray
                  if Wolf then
                    CallGlobal('SetTenon', 1, PartNo, FaceNo)
                  else if not Goat then
                    CallGlobal('SetGroove', 1, PartNo, FaceNo);
                  if Cabbage then
                    CallGlobal('SetTenon', 2, PartNo, FaceNo) // tenon "radius" = 2
                  else if not Goat then
                    CallGlobal('SetGroove', 2, PartNo, FaceNo);
                end;
            end;
